Lemma alloc_slot_mono lay f : forall R st sc req (k k' : mstate -> Z -> M R) bail bail',
  kle k k' -> tle bail bail' ->
  tle (alloc_slot lay f st sc req k bail) (alloc_slot lay (S f) st sc req k' bail').
Proof.
